command:
// Tag: Fold
// Run when someone steps into a fold. On a 7 or 8 it also rolls the vision, privately, for you to describe.
const table = name => game.tables.getName(name);
const glitch = table("Tag - Fold Glitch (d8)");
if (!glitch) return ui.notifications.error("Missing tables. Run Tag: Set Up the Meadow first.");
const { roll } = await glitch.draw();
const vision = { 7: "Fold Vision - The Record (d4)", 8: "Fold Vision - The Hunt (d4)" }[roll.total];
if (vision) await table(vision)?.draw({ rollMode: CONST.DICE_ROLL_MODES.PRIVATE });
